const BY_ID = new Map(SHELF.map((item) => [item.id, item]));

export function shelfWork(id: string) {
  return BY_ID.get(id);
}

export function readableIds() {
  return SHELF.filter((item) => isBoundReadable(item)).map((item) => item.id);
}

/** Lowercase + fold accents (NFD, strip combining marks) for shelf search. */
function foldSearchText(value: string) {
  return value.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
}

export function searchShelf(query: string) {
  const q = foldSearchText(query.trim());
  if (!q) return SHELF;
  return SHELF.filter((item) => {
    const blob = foldSearchText(
      `${item.title} ${item.author} ${item.year} ${item.form} ${item.language}`,
    );
    return q.split(/\s+/).every((word) => blob.includes(word));
  });
}